window.DSRExploration = {"plans":{"16":[["初访：离开牢房","取牢房钥匙 → 中庭篝火 → 从恶魔左侧门绕行。"],["奥斯卡与教学区","躲开滚球，与奥斯卡交谈取得原素瓶与钥匙；拾取初始装备。"],["不死院恶魔 → 鸟巢","从上层雾门进入战斗，出大门到悬崖前往祭祀场。"],["返访分支","从祭祀场鸟巢回来，探索牢房取得奇异人偶，使用西侧二层钥匙取生锈铁环；离群恶魔可后期挑战。"]],"8":[["建立补给点","点燃篝火，与失落战士、佩特鲁斯及出现的 NPC 对话。"],["环绕祭祀场收集","检查水池、遗迹、墓地与升降梯周边；地下防火女处可强化原素瓶。"],["主线：水道 → 不死镇","从山坡水道进入不死镇；小隆德和地下墓地是另外的分支。"],["返访与捷径","教区升降梯开放后可登上鸟巢返回不死院；敲钟、救人和王器进度会改变 NPC 位置。"]],"17":[["不死镇上层","篝火 → 不死商人 → 牛头恶魔；哈维尔塔楼为有钥匙时的分支。"],["飞龙桥 → 教区","见索拉尔，开启踢梯捷径；桥下经鼠道到教区，太阳祭坛为可选点。"],["教堂与安德烈","开启祭祀场升降梯，救罗特雷克，拜访安德烈；教堂楼顶石像鬼后敲第一口钟。"],["下层不死镇","用地下室钥匙进入下层，救古利格斯，山羊头恶魔后取得底层钥匙；女商人水道捷径可回祭祀场。"]],"6":[["厨房与上层水道","救劳伦提斯，检查屠夫旁宝箱与大块余烬；准备解毒与解除诅咒。"],["篝火与排水道","找房间篝火并打开连接上层的门；老鼠、咒蛙区域有落差和岔路。"],["贪食魔龙 → 病村","清理高处法师，检查多姆纳尔；击败魔龙获得病村钥匙。"]],"2":[["上层木架","从底层大门下降，依次检查平台、梯子与桥上的拾取点；不要把上下层距离当成可直行。"],["沼泽篝火与支线","到沼泽篝火；探索大树根入口，克拉娜与东方芝是否出现取决于剧情。"],["克拉格与第二口钟","进入白色洞穴挑战克拉格，敲第二口钟，再找白蜘蛛幻影墙。"],["水车返程","经水车向上，找小隆德遗迹钥匙；从飞龙之谷／小隆德返回祭祀场。"]],"4":[["庭院与隐藏篝火","从安德烈处进入，找徽章门旁幻影墙；月光蝶分支取得神圣余烬。"],["夹缝森林与九头蛇","探索山坡、黑骑士与底部篝火；湖水边缘有深渊落差。"],["希夫与契约","徽章门或湖边梯子进入庭院深处，找亚尔薇娜，挑战希夫取得亚尔特留斯的契约。"],["幽暗／DLC 前置","击败九头蛇后重载区域，救金色结晶怪中的幽暗；之后去书库取得破损项链，再回湖后传送点。"]],"14":[["机关大厅","敲响两口钟后进入；经过摆斧、蛇人与滚石楼梯。"],["中层分支","调整滚石方向，检查罗根囚室与贪欲金蛇戒指路线；下层楔形石恶魔区为可选。"],["屋顶与篝火","从屋顶边缘落到隐藏篝火；探索商人、笼子钥匙与笼梯捷径。"],["钢铁巨偶","先处理投掷火球的巨人；胜利后触摸光环前往亚诺尔隆德。"]],"0":[["大阶梯与绘画大厅","篝火 → 扶壁 → 房梁 → 旋转楼梯；有奇异人偶时可进入绘画世界。"],["银骑士建筑","通过弓箭手平台，抵达室内篝火和索拉尔；检查洋葱骑士、壁炉密室。"],["巨人铁匠与王器","开启大厅捷径，挑战翁斯坦与斯摩；上楼取得王器。"],["暗月分支","旋转楼梯降至底层，暗月灵庙戒指可开启葛温德林入口；是否挑战由你决定。"]],"13":[["外墙与庭院","从篝火沿建筑探索，开大门形成回路；有毒敌人死亡时保持距离。"],["地下井与附楼","探索车轮骷髅地下道，转动机关；找到别馆钥匙后探索别馆与余烬。"],["长桥与出口","经开放的大桥到普利希拉；可以和平离开，战斗和断尾为可选分支。"]],"10":[["上层小隆德","从祭祀场下行，准备暂时诅咒；探索鬼屋屋顶找到英果德。"],["放水与下层","取得封印钥匙，开闸放水；检查下层宝箱、巨大余烬与黑暗骑士。"],["四王","先从希夫取得并装备亚尔特留斯的契约，再进入深渊；卡斯路线还受王器交付对象影响。"],["飞龙之谷分支","连接病村、夹缝森林与小隆德；桥与山崖上的道具需另外绕行。"]],"3":[["首个篝火与机关","逐段清理死灵法师，转动桥梁；神圣武器可帮助控制复活骷髅。"],["隐藏通道与支线","检查桥边隐藏篝火和可破坏墙，寻找暗月灵庙戒指；石棺可进入墓王契约分支。"],["巴摩斯与底层","从螺旋阶梯分支下降到铁匠，进入车轮骷髅层。"],["三人尸术师","击败首领取得注火秘法，从梯子进入巨人墓地。"]],"15":[["照明与第一篝火","准备头盖骨提灯、太阳虫或照明魔法；沿巨型石棺逐层下降。"],["帕奇与蕾亚","探索帕奇陷阱下方并救蕾亚；再沿梯子返回，检查隐藏通道。"],["第二篝火与金色封印","探索巨兽区与下方通路；需要已放置王器才能通过金色封印。"],["墓王尼特","经洞穴到尼特；沿途余烬、戒指与拾取点可单独逐点导航。"]],"7":[["书库初访","放置王器解除金色封印；书库初战希斯后进入监牢。"],["监牢逃脱","取得钥匙，探索底层牢房与罗根线索；从上层门返回书库。"],["旋转楼梯与阳台","调整两座旋转楼梯，找阳台篝火、隐藏书柜、宝箱与庭院入口。"],["结晶洞穴","看落雪判断隐形地面，路线线条不保证隐形桥已安全对齐；摧毁结晶后挑战希斯。"],["罗根返访","完成罗根买卖与对话后回访最初希斯房间，处理法术与大块法术余烬分支。"]],"5":[["恶魔遗迹入口","从白蜘蛛区域向下；击败持续溃烂的生物使岩浆退去。"],["火焰司祭与百足恶魔","沿遗迹下行；金色封印需放置王器，百足战后取得焦黑橘色戒指。"],["废都岩浆区","装备戒指穿过岩浆，找塔内隐藏篝火；沿树根进入废都内部。"],["剧情与捷径分支","洋葱骑士、索拉尔和混沌仆人捷径均有条件；不要把候选 NPC 标记当成已出现。"],["混沌的温床","检查建筑与树根分支后到达首领雾门；崩塌地板需要自行判断。"]],"1":[["两重幻影墙","从病村的大树根依次打破两堵墙进入大树洞。"],["大树洞下降","沿树枝、梯子和平台分层收集；咒蛙与结晶蜥蜴分支可回访，不建议直接朝标记跳落。"],["灰烬湖","抵达沙滩篝火，沿湖岸与树根探索九头蛇附近的拾取点。"],["石之古龙","沿沙洲到末端古龙，契约与尾部武器为可选；回程可用篝火菜单。"]],"11":[["灵庙圣兽与灵庙","从幽暗传送入口到圣兽战，进入灵庙篝火并见伊丽莎白。"],["王家御苑","探索高低层与两座升降梯，开启回路；在亚尔特留斯前见切斯特。"],["亚尔特留斯与市镇","胜利后可见基亚兰；探索市镇、两处光照密门与牢房钥匙。"],["戈夫／黑龙分支","带钥匙回竞技场上方塔楼见戈夫；触发黑龙相关剧情后再挑战喀拉弥特。"],["深渊洞穴","从市镇地下到深渊；探索希夫救援支线，然后挑战马努斯并回访幽暗。"]],"9":[["王器与封印","向王器献上四份王魂／碎片，打开最终区域。"],["黑骑士道路","沿阶梯与灰烬道路收集黑骑士装备；逐点扫图会列出剩余固定拾取点。"],["乌薪王葛温","进入最终战前完成 DLC、契约、强化与收集；结局后直接进入下一周目。"]],"12":[["可选竞技场","乌拉席露竞技场仅供联机对战；不列入单机收集完成率。"]]},"mapIds":{"1000":6,"1001":17,"1002":8,"1100":13,"1200":4,"1201":11,"1300":3,"1301":15,"1302":1,"1400":2,"1401":5,"1500":14,"1501":0,"1600":10,"1700":7,"1800":9,"1801":16}};
